extends Node3D
## Сцена Мыса (техно-демка). Вид только читает sim: ввод -> sim.step в _physics_process, позиции -> узлы.
## Ось: плоскость sim (x, y) -> мир (x, высота, y); экран «вверх» = -y.
const Sim := preload("res://sim/sim.gd")
const Rng := preload("res://sim/rng.gd")
const LEVEL := "res://data/levels/cape.json"
const MODELS := "res://assets/models/"
const SEED := 1

var sim: RefCounted
var bal: Dictionary
var hero: Node3D
var cam: Camera3D
var focus := Vector3.ZERO
var prev_pos := Vector2.ZERO
var cur_pos := Vector2.ZERO
var prev_z := 0.0
var cur_z := 0.0
var anim_state := ""
var anim: Node  # view/hero_anim.gd, если есть


func _ready() -> void:
	sim = Sim.new(SEED, LEVEL)
	bal = sim.bal
	_build_environment()
	_build_ground()
	_build_props()
	_build_hero()
	_build_camera()
	cur_pos = sim.state.player["pos"]
	prev_pos = cur_pos
	focus = Vector3(cur_pos.x, 0.0, cur_pos.y)
	_place()


func _physics_process(_dt: float) -> void:
	var inp := {
		"move": Input.get_vector("move_left", "move_right", "move_up", "move_down"),
		"dash": Input.is_action_just_pressed("dash"),
		"jump": Input.is_action_just_pressed("jump"),
	}
	prev_pos = cur_pos
	prev_z = cur_z
	sim.step(inp)
	cur_pos = sim.state.player["pos"]
	cur_z = sim.state.player["z"]


func _process(dt: float) -> void:
	_place()
	var c: Dictionary = bal["camera"]
	var target := hero.position
	target.y = 0.0
	focus = focus.lerp(target, 1.0 - exp(-float(c["follow_rate"]) * dt))
	_aim_camera()
	_update_anim()


## Состояние героя из sim -> имя анимации (idle / run / dash / jump / land).
func hero_state() -> String:
	var p: Dictionary = sim.state.player
	if p["z"] > 0.0 or p["vz"] > 0.0:
		return "jump"
	if p["dash_left"] > 0:
		return "dash"
	if float(p["landed"]) > 0.0:
		return "land"
	if (p["vel"] as Vector2).length() > 0.5:
		return "run"
	return "idle"


func _update_anim() -> void:
	var s := hero_state()
	if s != anim_state:
		anim_state = s
		if anim != null:
			anim.call("play_state", s)


func _place() -> void:
	var f := Engine.get_physics_interpolation_fraction()
	var p := prev_pos.lerp(cur_pos, f)
	hero.position = Vector3(p.x, lerpf(prev_z, cur_z, f), p.y)
	var face: Vector2 = sim.state.player["facing"]
	hero.rotation.y = atan2(face.x, face.y)


func _aim_camera() -> void:
	var c: Dictionary = bal["camera"]
	var pitch := deg_to_rad(float(c["pitch_deg"]))
	var dir := Vector3(0.0, sin(pitch), cos(pitch))
	cam.position = focus + dir * float(c["distance"])
	cam.look_at(focus, Vector3.UP)


func _build_camera() -> void:
	var c: Dictionary = bal["camera"]
	cam = Camera3D.new()
	cam.fov = float(c["fov_deg"])
	cam.near = float(c["near"])
	cam.far = float(c["far"])
	cam.current = true
	add_child(cam)
	_aim_camera()


func _build_environment() -> void:
	var l: Dictionary = bal["light"]
	var env := Environment.new()
	env.background_mode = Environment.BG_COLOR
	env.background_color = Color(str(l["sky_color"]))
	env.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	env.ambient_light_color = Color(str(l["ambient_color"]))
	env.ambient_light_energy = float(l["ambient_energy"])
	var we := WorldEnvironment.new()
	we.environment = env
	add_child(we)
	var sun := DirectionalLight3D.new()
	sun.light_color = Color(str(l["sun_color"]))
	sun.light_energy = float(l["sun_energy"])
	sun.rotation_degrees = Vector3(-float(l["sun_pitch_deg"]), float(l["sun_yaw_deg"]), 0.0)
	sun.shadow_enabled = true
	sun.directional_shadow_max_distance = float(l["shadow_distance"])
	add_child(sun)


func _mat(color: Color) -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.albedo_color = color
	m.roughness = 1.0
	m.texture_filter = BaseMaterial3D.TEXTURE_FILTER_NEAREST
	return m


func _box(size: Vector3, pos: Vector3, mat: Material, yaw := 0.0) -> MeshInstance3D:
	var mi := MeshInstance3D.new()
	var bm := BoxMesh.new()
	bm.size = size
	mi.mesh = bm
	mi.material_override = mat
	mi.position = pos
	mi.rotation.y = yaw
	add_child(mi)
	return mi


func _build_ground() -> void:
	var g: Dictionary = bal["ground"]
	var b: Dictionary = sim.state.level["bounds"]
	var lo := Vector2(b["min"][0], b["min"][1])
	var hi := Vector2(b["max"][0], b["max"][1])
	var depth := float(g["cliff_depth"])
	var size := hi - lo + Vector2(depth, depth) * 2.0
	var mid := (lo + hi) * 0.5
	var sand := _mat(Color(str(g["sand_color"])))
	_box(Vector3(size.x, 0.5, size.y), Vector3(mid.x, -0.25, mid.y), sand)
	var rng := Rng.new(int(g["view_seed"]))
	var slab := _mat(Color(str(g["slab_color"])))
	var th := float(g["slab_thickness"])
	for _i in int(g["slab_count"]):
		var w := lerpf(float(g["slab_min"]), float(g["slab_max"]), rng.next_float())
		var d := lerpf(float(g["slab_min"]), float(g["slab_max"]), rng.next_float())
		var x := lerpf(lo.x, hi.x, rng.next_float())
		var y := lerpf(lo.y, hi.y, rng.next_float())
		_box(Vector3(w, th, d), Vector3(x, th * 0.5, y), slab, rng.next_float() * TAU)
	var rock := _mat(Color(str(g["rock_color"])))
	for _i in int(g["rock_count"]):
		# валуны по периметру, в полосе cliff_depth за границей арены
		var side := rng.range_int(0, 3)
		var t := rng.next_float()
		var o := lerpf(0.5, depth, rng.next_float())
		var p := Vector2.ZERO
		match side:
			0: p = Vector2(lerpf(lo.x, hi.x, t), lo.y - o)
			1: p = Vector2(lerpf(lo.x, hi.x, t), hi.y + o)
			2: p = Vector2(lo.x - o, lerpf(lo.y, hi.y, t))
			_: p = Vector2(hi.x + o, lerpf(lo.y, hi.y, t))
		var w := lerpf(float(g["rock_min"]), float(g["rock_max"]), rng.next_float())
		var h := lerpf(float(g["rock_height_min"]), float(g["rock_height_max"]), rng.next_float())
		if side == 0:
			h *= 1.6  # северный обрыв выше остальных
		_box(Vector3(w, h, w * 0.8), Vector3(p.x, h * 0.5 - 0.1, p.y), rock, rng.next_float() * TAU)


func _build_props() -> void:
	var l: Dictionary = bal["light"]
	for prop in sim.state.level["props"]:
		var scene := load(MODELS + str(prop["model"]) + ".glb") as PackedScene
		var node := scene.instantiate() as Node3D
		node.position = Vector3(float(prop["x"]), 0.0, float(prop["y"]))
		node.rotation_degrees.y = float(prop.get("yaw", 0.0))
		add_child(node)
		if str(prop["model"]) == "lighthouse":
			_setup_lighthouse(node, str(prop.get("state", "lit")) == "lit", l)


## В lighthouse.glb два состояния рядом по X (off = -8, lit = +8): оставляем одно и ставим башню в начало.
func _setup_lighthouse(node: Node3D, lit: bool, l: Dictionary) -> void:
	for child in node.get_children():
		var is_lit := child.name.begins_with("LH_lit")
		child.visible = (is_lit == lit)
		if child.visible:
			(child as Node3D).position.x = 0.0
	if lit:
		var lamp := OmniLight3D.new()
		lamp.light_color = Color(str(l["lamp_color"]))
		lamp.light_energy = float(l["lamp_energy"])
		lamp.omni_range = float(l["lamp_range"])
		lamp.shadow_enabled = true
		lamp.position = Vector3(0.0, float(l["lamp_height"]), 0.0)
		node.add_child(lamp)


func _build_hero() -> void:
	var scene := load(MODELS + "hero_caster.glb") as PackedScene
	hero = Node3D.new()
	hero.name = "Hero"
	add_child(hero)
	hero.add_child(scene.instantiate())
	var script := load("res://view/hero_anim.gd") if ResourceLoader.exists("res://view/hero_anim.gd") else null
	if script != null:
		anim = script.new()
		hero.add_child(anim)

