## Поворот в пространстве модели: сначала Z, затем Y, затем X (вокруг сустава).
func _rot(e: Vector3) -> Basis:
	return Basis(Vector3.RIGHT, e.x) * Basis(Vector3.UP, e.y) * Basis(Vector3.BACK, e.z)


## Поворот каждой кости задан в пространстве модели и несёт за собой потомков:
## глобальный = R * глобальный_родителя * rest_локальный, откуда локальный = P⁻¹·R·P·rest.
func _apply() -> void:
	for i in names.size():
		var par := skel.get_bone_parent(i)
		var rest := skel.get_bone_rest(i)
		var p: Basis = cur_g[par] if par >= 0 else Basis.IDENTITY
		var r := _rot(cur.get(names[i], Vector3.ZERO))
		var local_b := p.inverse() * r * p * rest.basis
		skel.set_bone_pose_rotation(i, local_b.get_rotation_quaternion())
		cur_g[i] = p * local_b
	skel.set_bone_pose_position(0, skel.get_bone_rest(0).origin + cur_pos)

